#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int co_loi = 0;
    for (int i = 0; i < n; i++) {
        char c;
        scanf(" %c", &c);
        if (c == 'n') co_loi = 1;
    }
    printf(co_loi ? "du\n" : "thieu\n");
    return 0;
}
